local graph = meldritch.graph()
local pitch = graph:module("pitch", "constant", { value = 440.0 })
local gate = graph:module("gate", "constant", { value = 0.0 })
local velocity = graph:module("velocity", "constant", { value = 1.0 })
local level = graph:module("level", "gain", { gain = 1.0 })
local output = graph:module("output", "output")
graph:connect(velocity.out, level.input)
graph:connect(gate.out, level.mod)
graph:connect(level.out, output.input)
graph:control("pitch", pitch, "value", { min = 8.0, max = 13000.0 })
graph:control("gate", gate, "value", { min = 0.0, max = 1.0 })
graph:control("velocity", velocity, "value", { min = 0.0, max = 1.0 })
graph:midi_notes(1, "pitch", "gate", "velocity")
return graph
